CREATE TABLE planning_sprints (workspace_id TEXT NOT NULL, id TEXT NOT NULL, project_id TEXT NOT NULL, name TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), closed INTEGER NOT NULL CHECK(closed IN (0,1)), PRIMARY KEY(workspace_id,id));
CREATE TABLE planning_items (workspace_id TEXT NOT NULL, sprint_id TEXT NOT NULL, issue_id TEXT NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), present INTEGER NOT NULL CHECK(present IN (0,1)), PRIMARY KEY(workspace_id,sprint_id,issue_id), FOREIGN KEY(workspace_id,sprint_id) REFERENCES planning_sprints(workspace_id,id));
CREATE UNIQUE INDEX planning_open_issue ON planning_items(workspace_id,issue_id) WHERE active=1;
CREATE TABLE planning_history (workspace_id TEXT NOT NULL, sprint_id TEXT NOT NULL, version INTEGER NOT NULL, action TEXT NOT NULL, issue_id TEXT, actor_id TEXT NOT NULL, occurred_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,sprint_id,version), FOREIGN KEY(workspace_id,sprint_id) REFERENCES planning_sprints(workspace_id,id));
CREATE TABLE planning_receipts (workspace_id TEXT NOT NULL, principal_id TEXT NOT NULL, operation_id TEXT NOT NULL, fingerprint TEXT NOT NULL, result_id TEXT NOT NULL, result_version INTEGER NOT NULL, PRIMARY KEY(workspace_id,principal_id,operation_id));
CREATE TABLE planning_events (workspace_id TEXT NOT NULL, sequence INTEGER NOT NULL, event_id TEXT NOT NULL, aggregate_id TEXT NOT NULL, aggregate_version INTEGER NOT NULL, type TEXT NOT NULL, issue_id TEXT, actor_id TEXT NOT NULL, occurred_at INTEGER NOT NULL, PRIMARY KEY(workspace_id,sequence), UNIQUE(workspace_id,event_id));
CREATE TABLE planning_guards (workspace_id TEXT NOT NULL, id TEXT NOT NULL, changed INTEGER NOT NULL CHECK(changed=1), PRIMARY KEY(workspace_id,id));
